async function requisicaoSeguraFlask(url, opcoes = {}) {
    const tokenJWT = await firebase.auth().currentUser.getIdToken(true);
    opcoes.headers = { Authorization: `Bearer ${tokenJWT}`, 'Content-Type': 'application/json', ...opcoes.headers };
    const resposta = await fetch(url, opcoes);
    if (resposta.status === 401) window.location.href = '/login';
    return resposta.json();
}

async function iniciarCheckoutSaaS(idPlanoPreco) {
    const respostaSessao = await requisicaoSeguraFlask('/api/faturamento/criar-checkout', { method: 'POST', body: JSON.stringify({ precoId: idPlanoPreco }) });
    window.location.href = respostaSessao.url_redirecionamento;
}
